// Mode: Run Once for All Items
const candidates = [
  {
    candidate_name: "Budi Santoso",
    position: "DevOps Engineer",
    claimed_skills: ["Kubernetes", "Docker", "CI/CD", "Terraform"],
    past_company_type: "Startup fintech dengan traffic tinggi"
  },
  {
    candidate_name: "Sari Wulandari",
    position: "Backend Engineer",
    claimed_skills: ["Node.js", "PostgreSQL", "Redis", "REST API"],
    past_company_type: "Perusahaan e-commerce skala besar"
  }
];

return candidates.map(c => ({ json: c }));

// Mode: Run Once for Each Item
const c = $input.item.json;

const user_prompt = `Data kandidat:
- Nama: ${c.candidate_name}
- Posisi yang dilamar: ${c.position}
- Skill yang diklaim: ${c.claimed_skills.join(", ")}
- Latar belakang perusahaan sebelumnya: ${c.past_company_type}

Buatlah SATU pertanyaan studi kasus troubleshooting yang relevan dengan skill dan latar belakang kandidat di atas.`;

return { json: { ...c, user_prompt } };

// Mode: Run Once for Each Item
// Simulasi jawaban kandidat: Budi = jawaban teknis, selain Budi = jawaban generik
const question = $json.text;
const c = $('Prompt Builder').item.json;

let candidate_answer;
if (c.candidate_name.includes("Budi")) {
  candidate_answer = `Pertama saya cek status pod dengan kubectl get pods dan kubectl describe pod untuk melihat event (OOMKilled / CrashLoopBackOff). Lalu saya lihat log dengan kubectl logs --previous dan cek resource limit/request. Kalau OOM, saya analisis memory profile, naikkan limit sementara, lalu cari memory leak. Terakhir saya cek metrik di Prometheus/Grafana, pasang alert, dan tulis postmortem agar tidak terulang.`;
} else {
  candidate_answer = `Saya akan mengecek masalahnya dulu, lalu mencoba memperbaikinya. Kalau belum berhasil, saya tanya tim atau cari solusi di internet. Yang penting tetap tenang dan bekerja sama dengan tim.`;
}

return { json: { candidate_name: c.candidate_name, position: c.position, question, candidate_answer } };

// Mode: Run Once for Each Item
const { candidate_name, position, question, candidate_answer } = $input.item.json;

const eval_prompt = `Posisi: ${position}
Kandidat: ${candidate_name}

Question Given:
${question}

Candidate Answer:
${candidate_answer}

Nilai jawaban kandidat sesuai rubrik dan format yang diminta.`;

return { json: { candidate_name, position, question, candidate_answer, eval_prompt } };
